104	ge::graphStatus AHInfoParser::CheckInputValid()
105	{
106	    // 1.获取变量相关参数
107	    opParamInfo_.input.desc = context_->GetInputDesc(INPUT_INDEX);
108	    opParamInfo_.input.shape = context_->GetInputShape(INPUT_INDEX);
109	    // 2.检查变量是否存在
110	    OP_CHECK_IF(opParamInfo_.input.shape == nullptr,
111	        OP_LOGE(opName_, "Shape of tensor input is nullptr"),
112	        return ge::GRAPH_FAILED);
113	    OP_CHECK_IF(opParamInfo_.input.desc == nullptr,
114	        OP_LOGE(opName_, "Desc of tensor input is nullptr"),
115	        return ge::GRAPH_FAILED);
116	    // 3.检查变量类型
117	    inputType_ = opParamInfo_.input.desc->GetDataType();
118	    OP_CHECK_IF(((inputType_ != ge::DT_FLOAT16) && (inputType_ != ge::DT_BF16)),
119	        OP_LOGE(opName_, "The data types of the input must be float16 or bfloat16."),
120	        return ge::GRAPH_FAILED);
121	    // 4.检查变量Shape的Dim
122	    int64_t inputShapeDim = opParamInfo_.input.shape->GetStorageShape().GetDimNum();
123	    int64_t inputExpectShapeDim = DIM_NUM_THREE;
124	    OP_CHECK_IF(inputShapeDim != inputExpectShapeDim,
125	        OP_LOGE(
